  "characters[char-kiba].rank": "Jônin",
  "characters[char-kiba].shortDescription": "Combat en tandem avec le chien ninja Akamaru.",
  "characters[char-kiba].abilities[0]": "Imitation bestiale",
  "characters[char-kiba].abilities[1]": "Crocs sur crocs",
  "characters[char-hinata].rank": "Chûnin / Jônin",
  "characters[char-hinata].shortDescription": "Héritière du clan Hyûga. Amoureuse de Naruto depuis l'enfance.",
  "characters[char-hinata].abilities[0]": "Byakugan",
  "characters[char-hinata].abilities[1]": "Poing souple",
  "characters[char-hinata].abilities[2]": "Poings des lions jumeaux",
