  "characters[char-shino].rank": "Jônin",
  "characters[char-shino].shortDescription": "Spécialiste des insectes kikaichû, ninja sensoriel et pisteur.",
  "characters[char-shino].abilities[0]": "Manipulation des insectes",
  "characters[char-shino].abilities[1]": "Clone d'insectes",
  "characters[char-rock-lee].rank": "Jônin",
  "characters[char-rock-lee].shortDescription": "Spécialiste du taijutsu et élève préféré de Gaï Maito.",
