  "characters[char-izuna].abilities[0]": "Mangekyô Sharingan",
  "characters[char-izuna].kekkeiGenkai[0]": "Sharingan",
  "characters[char-izuna].longDescription": "Le petit frère de Madara, qui partage son Sharingan. Mortellement blessé par Tobirama, il lègue ses yeux à Madara, qui s'en sert pour obtenir le Mangekyô Sharingan éternel.",
  "characters[char-obito].aliases[0]": "Tobi",
