  "characters[char-fugaku].kekkeiGenkai[0]": "Sharingan",
  "characters[char-mikoto].shortDescription": "Mère d'Itachi et de Sasuke.",
  "characters[char-mikoto].longDescription": "La mère d'Itachi et de Sasuke, épouse de Fugaku. La nuit du massacre, elle accepte son sort aux côtés de son mari, demandant seulement à Itachi d'épargner son frère : Itachi la tue en larmes.",
  "characters[char-pain].aliases[0]": "Six Voies de Pain",
