  "characters[char-yahiko].shortDescription": "Fondateur de l'Akatsuki originelle. Le visage du corps de la Voie des Deva de Pain.",
  "characters[char-deidara].rank": "Akatsuki",
  "characters[char-deidara].shortDescription": "Membre de l'Akatsuki originaire d'Iwa, un artiste explosif qui travaille l'argile.",
