  "routes[route-char-madara].description": "Madara Uchiwa, de la fondation de Konoha avec Hashirama à la bataille de la Vallée de la Fin, du plan du Tsukuyomi infini confié à Obito à son retour pendant la quatrième guerre et à la trahison de Zetsu noir.",
